/* DOM/event unit tests; deliberately no browser, layout engine or remote images. */
const test=require('node:test'),assert=require('node:assert/strict'),vm=require('node:vm'),fs=require('node:fs');
function environment(){const dialogs=[],base=new Map;const attr=(s,k)=>new RegExp('(?:^|\\s)'+k+'="([^"]*)"').exec(s)?.[1];
 class El{constructor(tag='div'){this.tag=tag;this.nodes=[];this.style={};this.dataset={};this.classList={add(){},remove(){}};this.value='';this.disabled=false;this._html='';this.textContent='';}set innerHTML(v){this._html=v;this.nodes=[];for(const m of v.matchAll(/<(select|button|input|p|div)([^>]*)>(?:([\s\S]*?)<\/\1>)?/g)){const n=new El(m[1]),a=m[2];n.id=attr(a,'id');n.disabled=/\bdisabled\b/.test(a);for(const d of a.matchAll(/data-([a-z-]+)="([^"]*)"/g))n.dataset[d[1].replace(/-([a-z])/g,(_,x)=>x.toUpperCase())]=d[2];if(m[1]==='select'){const os=[...(m[3]||'').matchAll(/<option([^>]*)>/g)];n.value=attr((os.find(o=>/\bselected\b/.test(o[1]))||os[0]||[])[1]||'','value')||'';}else n.value=attr(a,'value')||'';this.nodes.push(n);} // separately index all ID and select elements, including nested markup
 for(const m of v.matchAll(/<select([^>]*)>([\s\S]*?)<\/select>/g)){const a=m[1];const n=new El('select');n.id=attr(a,'id');n.disabled=/\bdisabled\b/.test(a);for(const d of a.matchAll(/data-([a-z-]+)="([^"]*)"/g))n.dataset[d[1].replace(/-([a-z])/g,(_,x)=>x.toUpperCase())]=d[2];const os=[...m[2].matchAll(/<option([^>]*)>/g)];n.value=attr((os.find(o=>/\bselected\b/.test(o[1]))||os[0]||[])[1]||'','value')||'';this.nodes=this.nodes.filter(x=>!(n.id&&x.id===n.id)&&!(n.dataset.field&&x.dataset.field===n.dataset.field)&&!(n.dataset.pay&&x.dataset.pay===n.dataset.pay));this.nodes.push(n);}
 for(const m of v.matchAll(/<(button|p|div|input)([^>]*)\bid="([^"]+)"([^>]*)>/g)){if(!this.nodes.some(x=>x.id===m[3])){const n=new El(m[1]);n.id=m[3];n.disabled=/\bdisabled\b/.test(m[2]+m[4]);this.nodes.push(n);}}

 for(const m of v.matchAll(/<input([^>]*)>/g)){const a=m[1],n=new El('input');n.id=attr(a,'id');n.value=attr(a,'value')||'';n.checked=/\bchecked\b/.test(a);n.disabled=/\bdisabled\b/.test(a);for(const d of a.matchAll(/data-([a-z-]+)="([^"]*)"/g))n.dataset[d[1].replace(/-([a-z])/g,(_,x)=>x.toUpperCase())]=d[2];this.nodes=this.nodes.filter(x=>!(n.id&&x.id===n.id)&&!(n.dataset.combatSelect&&x.dataset.combatSelect===n.dataset.combatSelect)&&!(n.dataset.web&&x.dataset.web===n.dataset.web));this.nodes.push(n);}
 }get innerHTML(){return this._html;}querySelector(s){return s.startsWith('#')?this.nodes.find(n=>n.id===s.slice(1))||null:null;}querySelectorAll(s){if(s==='img')return [];const key=/^\[data-([a-z-]+)\]$/.exec(s)?.[1]?.replace(/-([a-z])/g,(_,x)=>x.toUpperCase());return key?this.nodes.filter(n=>n.dataset[key]!==undefined):[];}showModal(){dialogs.push(this);}close(){}remove(){const i=dialogs.indexOf(this);if(i>=0)dialogs.splice(i,1);}addEventListener(){}click(){if(!this.disabled&&this.onclick)this.onclick();}}
 for(const id of ['app','toast','undo','export','import','tableTab','catalogTab','playersTab','imagesTab','helpTab']){let e=new El;e.id=id;base.set(id,e);}
 const document={querySelector:s=>base.get(s.slice(1))||base.get('app').querySelector(s),querySelectorAll:()=>[],createElement:t=>new El(t),body:{append(){}}};
 const ctx=vm.createContext({module:undefined,document,localStorage:{getItem:()=>null,setItem(){},removeItem(){}},setTimeout:()=>1,clearTimeout(){},console,Blob,URL,confirm:()=>true});
 for(const f of ['data.js','starter-decks.js','player-cards.js','ringsdb-snapshot.js','planning-engine.js','quest-engine.js','travel-engine.js','encounter-engine.js','combat-engine.js','refresh-engine.js','window-engine.js','engine.js','score-engine.js','player-ui.js','image-index.js','encounter-image-index.js','chinese-core-images.js','image-ui.js','planning-ui.js','quest-ui.js','travel-ui.js','encounter-ui.js','combat-ui.js','refresh-ui.js','window-ui.js','desktop-ui.js','product-catalog.js','app.js'])vm.runInContext(fs.readFileSync(__dirname+'/'+f,'utf8'),ctx,{filename:f});
 const run=s=>vm.runInContext(s,ctx);const click=d=>run(`$('#app').onclick({target:{closest:()=>({dataset:${JSON.stringify(d)}})}})`);
 return {ctx,run,click,dialogs,base};
}
async function opening(e,sphere='leadership'){await e.click({action:'starterTest',sphere});e.run("document.querySelector('#seed').value='12345';");await e.click({action:'start',id:'mirkwood'});e.run("E.windows.setMode(state,'detailed');");await e.click({action:'keepHand',player:'0'});await e.click({action:'finishSetup'});await e.click({action:'next'});}
test('planning UI cancel is read-only, payment allocation controls sum, and confirm moves a real ally to board',async()=>{const e=environment();await opening(e);e.run(`{const p=state.players[0];const i=p.playerDeck.findIndex(c=>c.code==='01013');if(!p.hand.some(c=>c.code==='01013'))p.hand.push(p.playerDeck.splice(i,1)[0]);}`);const uid=e.run("state.players[0].hand.find(c=>c.code==='01013').uid"),before=e.run('JSON.stringify(state)');let action=e.click({action:'planning',plan:'play',player:'0',uid:String(uid)});let d=e.dialogs.at(-1);assert(d);d.querySelector('#plan-cancel').click();await action;assert.equal(e.run('JSON.stringify(state)'),before);
 action=e.click({action:'planning',plan:'play',player:'0',uid:String(uid)});d=e.dialogs.at(-1);const ps=d.querySelectorAll('[data-pay]'),paid=ps.find(p=>Number(p.value)>0),old=paid.value;paid.value='0';paid.onchange();assert(d.querySelector('#plan-confirm').disabled);paid.value=old;paid.onchange();assert(!d.querySelector('#plan-confirm').disabled);d.querySelector('#plan-confirm').click();await action;assert.equal(e.run('state.players[0].allies.length'),1);assert.equal(e.run('state.players[0].heroStates.reduce((n,h)=>n+h.resources,0)'),1);assert(e.base.get('app').innerHTML.includes('盟友区 · 1'));});
test('planning UI resolves optional Scout response and ends with explicit pass and phase-2 acceptance',async()=>{const e=environment();await opening(e);e.run(`{const p=state.players[0];let x=p.hand.find(c=>c.code==='01016');if(!x){let i=p.playerDeck.findIndex(c=>c.code==='01016');p.hand.push(p.playerDeck.splice(i,1)[0]);}}`);let uid=e.run("state.players[0].hand.find(c=>c.code==='01016').uid");let a=e.click({action:'planning',plan:'play',player:'0',uid:String(uid)});e.dialogs.at(-1).querySelector('#plan-confirm').click();await a;assert.equal(e.run('state.planning.queue[0].kind'),'entry');let id=e.run('state.planning.queue[0].id');a=e.click({action:'planning',plan:'choice',id:String(id)});let d=e.dialogs.at(-1);assert(d.querySelectorAll('[data-field]').length);d.querySelector('#plan-confirm').click();await a;assert.equal(e.run('state.staging.find(c=>c.id===99).progress'),1);await e.click({action:'planning',plan:'endTurn',player:'0'});await e.click({action:'planning',plan:'pass',player:'0'});await e.click({action:'next'});assert.equal(e.run('state.planning.completed'),true);assert.equal(e.run('state.phase'),1);assert(e.base.get('app').innerHTML.includes('阶段2 · 计划阶段验收完成'));});

test('all four starter tables and hand images resolve to local Chinese Core assets',async()=>{for(const sp of ['leadership','tactics','spirit','lore']){const e=environment();await opening(e,sp);const markup=e.base.get('app').innerHTML;assert(markup.includes('assets/cards-zh-core/'));for(const code of e.run('state.players[0].heroCodes'))assert(markup.includes('assets/cards-zh-core/'+code+'.jpg'));assert(!/src="https:\/\/ringsdb.com/.test(markup));}});

test('all four starter UI flows enter phase3, commit nobody, stage one card and finish at phase3',async()=>{for(const sphere of ['leadership','tactics','spirit','lore']){const e=environment();await opening(e,sphere);await e.click({action:'planning',plan:'endTurn',player:'0'});await e.click({action:'planning',plan:'pass',player:'0'});await e.click({action:'next'});assert(e.base.get('app').innerHTML.includes('进入探险阶段'));await e.click({action:'next'});assert.equal(e.run('state.phase'),2);assert(!e.base.get('app').innerHTML.includes('id="willpower"'));for(const step of [0,1]){await e.click({action:'quest',quest:'pass',player:'0'});await e.click({action:'quest',quest:'move'});if(step===0){const action=e.click({action:'quest',quest:'commit',player:'0'});e.dialogs.at(-1).querySelector('#ok').click();await action;await e.click({action:'quest',quest:'approveDeployment',player:'0'});}}e.run(`{const c={...E.byId[97],uid:++state.serial};state.deck.unshift(c);}`);await e.click({action:'quest',quest:'draw'});assert(e.base.get('app').innerHTML.includes('结算此牌的关键词与效果'));await e.click({action:'quest',quest:'reveal'});await e.click({action:'quest',quest:'draw'});await e.click({action:'quest',quest:'pass',player:'0'});await e.click({action:'quest',quest:'move'});assert(e.base.get('app').innerHTML.includes('本次结果'));await e.click({action:'quest',quest:'pass',player:'0'});await e.click({action:'quest',quest:'move'});assert.equal(e.run('state.questing.completed'),true);assert(e.base.get('app').innerHTML.includes('阶段3 · 探险阶段验收完成'));}});
test('quest UI native choice executes Aragorn ready and shows him still committed',async()=>{const e=environment();await opening(e);await e.click({action:'planning',plan:'endTurn',player:'0'});await e.click({action:'planning',plan:'pass',player:'0'});await e.click({action:'next'});await e.click({action:'next'});await e.click({action:'quest',quest:'pass',player:'0'});await e.click({action:'quest',quest:'move'});e.run(`E.questing.commit(state,0,[state.players[0].heroStates[0].uid]);render();`);const id=e.run('state.questing.tasks[0].id');const result=e.click({action:'quest',quest:'choice',id:String(id)});const d=e.dialogs.at(-1);assert(d);d.querySelector('#ok').click();await result;assert.equal(e.run('state.players[0].heroStates[0].exhausted'),false);assert.equal(e.run('state.players[0].heroStates[0].committed'),true);assert(e.base.get('app').innerHTML.includes('已投入：阿拉贡'));});

async function commitScreen(e){await opening(e);await e.click({action:'planning',plan:'endTurn',player:'0'});await e.click({action:'planning',plan:'pass',player:'0'});await e.click({action:'next'});await e.click({action:'next'});await e.click({action:'quest',quest:'pass',player:'0'});await e.click({action:'quest',quest:'move'});}
test('quest deployment review and cancel do not mutate state/history and retain the draft across rendering',async()=>{const e=environment();await commitScreen(e);const uid=e.run('state.players[0].heroStates[0].uid');e.run(`QuestUI.setDraft(state,0,[${uid}]);render();`);const before=e.run('JSON.stringify(state)'),count=e.run('history.length');let result=e.click({action:'quest',quest:'commit',player:'0'});const d=e.dialogs.at(-1);assert(d.innerHTML.includes('阿拉贡'));assert(d.innerHTML.includes('意志合计'));assert.equal(e.run('JSON.stringify(state)'),before);d.querySelector('#cancel').click();await result;assert.equal(e.run('JSON.stringify(state)'),before);assert.equal(e.run('history.length'),count);assert.equal(e.run('JSON.stringify(QuestUI.draftFor(state,0))'),JSON.stringify([uid]));assert(e.base.get('app').innerHTML.includes('aria-pressed="true"'));assert(e.base.get('app').innerHTML.includes('selection-mark'));await e.click({action:'quest',quest:'clear',player:'0'});assert.equal(e.run('QuestUI.draftFor(state,0).length'),0);assert.equal(e.run('JSON.stringify(state)'),before);assert.equal(e.run('history.length'),count);});
test('review confirmation commits exactly the selected draft; local back restores full state and responses',async()=>{const e=environment();await commitScreen(e);const uid=e.run('state.players[0].heroStates[0].uid');e.run(`QuestUI.setDraft(state,0,[${uid}]);render();`);const before=e.run('JSON.stringify(state)');const result=e.click({action:'quest',quest:'commit',player:'0'});e.dialogs.at(-1).querySelector('#ok').click();await result;await e.click({action:'quest',quest:'approveDeployment',player:'0'});assert.equal(e.run('state.players[0].heroStates[0].committed'),true);assert.equal(e.run('state.players[0].heroStates[1].committed'),false);assert.equal(e.run('state.questing.tasks.length'),1);const afterCommit=e.run('JSON.stringify(state)');e.run(`mutate(()=>E.questing.choose(state,state.questing.tasks[0].id,{}));`);assert.equal(e.run('state.players[0].heroStates[0].resources'),0);await e.click({action:'quest',quest:'back'});assert.equal(e.run('JSON.stringify(state)'),afterCommit);await e.click({action:'quest',quest:'back'});assert.equal(e.run('state.questing.deploymentLocked'),undefined);await e.click({action:'quest',quest:'back'});assert.equal(e.run('JSON.stringify(state)'),before);assert.equal(e.run('state.players[0].heroStates[0].exhausted'),false);assert.equal(e.run('state.questing.tasks.length'),0);});
test('stale deployment review is rejected without committing or discarding later state',async()=>{const e=environment();await commitScreen(e);const uid=e.run('state.players[0].heroStates[0].uid');e.run(`QuestUI.setDraft(state,0,[${uid}]);`);const result=e.click({action:'quest',quest:'commit',player:'0'});e.run('state.players[0].heroStates[0].resources++;');const changed=e.run('JSON.stringify(state)');e.dialogs.at(-1).querySelector('#ok').click();await result;assert.equal(e.run('JSON.stringify(state)'),changed);assert(e.base.get('toast').textContent.includes('桌面已变化'));});

test('multiplayer UI exposes cancel confirmation until final player submits, then locks and applies the revised selection',async()=>{const e=environment();e.run(`{const cfg=['leadership','spirit'].map(sp=>PlayerCards.config(PlayerCards.starter(PlayerUI.getSnapshot(),sp),PlayerUI.getSnapshot()));state=E.create('mirkwood',2,12345,cfg,{deferSetup:true});E.openingChoice(state,0);E.openingChoice(state,1);E.startScenario(state);E.nextPhase(state);E.planning.endTurn(state,0);E.planning.endTurn(state,1);E.planning.passAction(state,0);E.planning.passAction(state,1);E.nextPhase(state);E.nextPhase(state);E.questing.pass(state,0);E.questing.pass(state,1);E.questing.move(state);handView=0;QuestUI.setDraft(state,0,[state.players[0].heroStates[0].uid]);render();}`);let action=e.click({action:'quest',quest:'commit',player:'0'});e.dialogs.at(-1).querySelector('#ok').click();await action;assert(e.base.get('app').innerHTML.includes('取消确认，修改派遣'));assert.equal(e.run('state.players[0].heroStates[0].exhausted'),false);await e.click({action:'quest',quest:'withdraw',player:'0'});assert(!e.run('state.questing.deployments[0].confirmed'));e.run('QuestUI.setDraft(state,0,[]);');action=e.click({action:'quest',quest:'commit',player:'0'});e.dialogs.at(-1).querySelector('#ok').click();await action;e.run('handView=1;render();');assert(e.base.get('app').innerHTML.includes('玩家1：已提交（可更改）'));action=e.click({action:'quest',quest:'commit',player:'1'});e.dialogs.at(-1).querySelector('#ok').click();await action;assert.equal(e.run('state.questing.deploymentLocked'),true);assert.equal(e.run('state.questing.step'),'afterCommit');assert(e.run('state.players.every(p=>p.heroStates.every(h=>!h.committed))'));assert(!e.base.get('app').innerHTML.includes('取消确认，修改派遣'));});

test('discussion UI queues an event, permits cancellation without cost, then executes only on secondary confirmation',async()=>{const e=environment();await opening(e);await e.click({action:'planning',plan:'endTurn',player:'0'});await e.click({action:'planning',plan:'pass',player:'0'});await e.click({action:'next'});await e.click({action:'next'});e.run(`{const p=state.players[0];if(!p.hand.some(c=>c.code==='01022')){const i=p.playerDeck.findIndex(c=>c.code==='01022');p.hand.push(p.playerDeck.splice(i,1)[0]);}render();}`);const uid=e.run("state.players[0].hand.find(c=>c.code==='01022').uid"),resources=e.run('state.players[0].heroStates.reduce((n,h)=>n+h.resources,0)');for(let i=0;i<2;i++){const action=e.click({action:'planning',plan:'play',player:'0',uid:String(uid)});const d=e.dialogs.at(-1);assert(d.innerHTML.includes('加入暂定清单'));d.querySelector('#plan-confirm').click();await action;assert.equal(e.run('state.questing.plannedActions.length'),1);assert.equal(e.run('state.players[0].heroStates.reduce((n,h)=>n+h.resources,0)'),resources);assert(e.base.get('app').innerHTML.includes('暂定行动 · 交流缓冲区'));if(i===0)await e.click({action:'quest',quest:'cancelAction',player:'0',id:String(e.run('state.questing.plannedActions[0].id'))});}await e.click({action:'quest',quest:'approveActions',player:'0'});assert.equal(e.run('state.questing.plannedActions.length'),0);assert.equal(e.run('state.players[0].heroStates.reduce((n,h)=>n+h.resources,0)'),resources-2);assert(e.run(`state.players[0].playerDiscard.some(c=>c.uid===${uid})`));await e.click({action:'quest',quest:'pass',player:'0'});assert(e.base.get('app').innerHTML.includes('取消放弃行动'));await e.click({action:'quest',quest:'unpass',player:'0'});assert.equal(e.run('state.questing.finalPasses.length'),0);});
test('discussion UI leaves a second confirmation buffer after the whole table submits deployment',async()=>{const e=environment();await commitScreen(e);e.run('QuestUI.setDraft(state,0,[state.players[0].heroStates[0].uid]);');const action=e.click({action:'quest',quest:'commit',player:'0'});e.dialogs.at(-1).querySelector('#ok').click();await action;assert(e.base.get('app').innerHTML.includes('派遣交流与缓冲期'));assert(e.base.get('app').innerHTML.includes('二次确认派遣'));assert.equal(e.run('state.players[0].heroStates[0].exhausted'),false);assert.equal(e.run('state.questing.tasks.length'),0);await e.click({action:'quest',quest:'withdraw',player:'0'});assert.equal(e.run('state.questing.deployments[0].confirmed'),false);assert.equal(e.run('state.players[0].heroStates[0].committed'),false);});

test('four starter UI flows advance from completed phase3 to travel, ready Old Forest Road target and finish phase4',async()=>{for(const sphere of ['leadership','tactics','spirit','lore']){const e=environment();await commitScreen(e);let action=e.click({action:'quest',quest:'commit',player:'0'});e.dialogs.at(-1).querySelector('#ok').click();await action;await e.click({action:'quest',quest:'approveDeployment',player:'0'});await e.click({action:'quest',quest:'pass',player:'0'});await e.click({action:'quest',quest:'move'});e.run(`state.deck.unshift({...E.byId[97],uid:++state.serial});`);await e.click({action:'quest',quest:'draw'});await e.click({action:'quest',quest:'reveal'});await e.click({action:'quest',quest:'draw'});await e.click({action:'quest',quest:'pass',player:'0'});await e.click({action:'quest',quest:'move'});await e.click({action:'quest',quest:'pass',player:'0'});await e.click({action:'quest',quest:'move'});assert.equal(e.run('state.questing.completed'),true);const q=e.run('JSON.stringify(state.questing)'),round=e.run('state.round');assert(e.base.get('app').innerHTML.includes('进入第四阶段 · 旅行'));await e.click({action:'next'});assert.equal(e.run('state.phase'),3);assert.equal(e.run('JSON.stringify(state.questing)'),q);assert.equal(e.run('state.round'),round);assert(e.base.get('app').innerHTML.includes('阶段4 · 旅行选择与全队确认'));e.run('state.players[0].heroStates[0].exhausted=true;render();');const uid=e.run('state.staging.find(c=>c.id===99).uid');action=e.click({action:'travelFlow',travel:'propose',uid:String(uid)});e.dialogs.at(-1).querySelector('#ok').click();await action;assert.equal(e.run('state.active'),null);assert(e.base.get('app').innerHTML.includes('二次确认旅行'));await e.click({action:'travelFlow',travel:'approve',player:'0'});assert.equal(e.run('state.active.id'),99);const id=e.run('state.traveling.tasks[0].id');action=e.click({action:'travelFlow',travel:'choice',id:String(id)});e.dialogs.at(-1).querySelector('#travel-confirm').click();await action;assert.equal(e.run('state.players[0].heroStates[0].exhausted'),false);if(e.run('state.traveling.tasks.length')){action=e.click({action:'travelFlow',travel:'choice',id:String(e.run('state.traveling.tasks[0].id'))});e.dialogs.at(-1).querySelector('#travel-skip').click();await action;}await e.click({action:'travelFlow',travel:'pass',player:'0'});await e.click({action:'travelFlow',travel:'finish'});assert.equal(e.run('state.traveling.completed'),true);assert(e.base.get('app').innerHTML.includes('阶段4 · 旅行阶段验收完成'));await e.click({action:'next'});assert.equal(e.run('state.phase'),4);assert.equal(e.run('state.encountering.step'),'optional');assert.equal(e.run('JSON.stringify(state.questing)'),q);await e.click({action:'encounterFlow',encounter:'skip',player:'0'});await e.click({action:'encounterFlow',encounter:'approve',player:'0'});assert.equal(e.run('state.encountering.step'),'beforeChecks');await e.click({action:'encounterFlow',encounter:'pass',player:'0'});await e.click({action:'encounterFlow',encounter:'checks'});assert.equal(e.run('state.encountering.step'),'afterChecks');await e.click({action:'encounterFlow',encounter:'pass',player:'0'});await e.click({action:'encounterFlow',encounter:'finish'});assert.equal(e.run('state.encountering.completed'),true);assert(e.base.get('app').innerHTML.includes('阶段5 · 遭遇阶段验收完成'));await e.click({action:'next'});assert.equal(e.run('state.phase'),5);assert(e.base.get('app').innerHTML.includes('阶段6 · 敌人攻击前行动'));}});

function encounterScreen(e){e.run(`(()=>{const R=E.planning,Q=E.questing,T=E.traveling;const cfg=['leadership','spirit'].map(sp=>PlayerCards.config(PlayerCards.starter(RINGSDB_SNAPSHOT,sp),RINGSDB_SNAPSHOT));state=E.create('mirkwood',2,12345,cfg,{deferSetup:true,openingTest:true});for(const p of state.players)E.openingChoice(state,p.id);E.startScenario(state);E.nextPhase(state);while(R.active(state)!==null)R.endTurn(state,R.active(state));for(const p of state.players)R.passAction(state,p.id);E.nextPhase(state);E.nextPhase(state);for(const step of [0,1,2,3]){if(step===1)for(const id of state.questing.order)Q.commit(state,id,[]);if(step===2){state.staging=[];state.questing.remaining=[];state.questing.step='staging';Q.drawNext(state);}for(const p of state.players)Q.pass(state,p.id);Q.move(state);}E.nextPhase(state);T.propose(state,state.first,null);for(const p of state.players)T.approve(state,p.id);for(const p of state.players)Q.pass(state,p.id);T.finish(state);E.nextPhase(state);history=[];render();})();`);}
